function [s] = emu_scale()
%EMU_SCALE  The scaling as the drivers read it: drv_read of a frame of each kind holding one count in its first field (the
%   star tracker's and the GNSS receiver's UART frames made by the drivers' uart_stream, a rotor's CAN telemetry), the
%   fields' ranges by rd16 and rd32, the command words' full scale by q15 of 1.
%   returns s: EmuScale (passed rec)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    s = asils.models.emucodec.EmuScale_zero();
    s = asils.models.emucodec.EmuScale_zero();
    one = [1; 1; 0; 0; 0; 0; 0];
    gyro_rx = zeros(13, 1);
    gyro_rx(1) = 1;
    gyro_rx(2) = 1;
    junk = zeros(8, 1);
    stp = zeros(36, 1);
    stp(1) = 1;
    stp(2) = 1;
    stp(3) = 1;
    [st, st_len] = asils.models.drivers.uart_stream(junk, 0, stp, 18, 144, 0, 1);
    gpp = zeros(36, 1);
    gpp(1) = 1;
    gpp(2) = 1;
    gpp(14) = 1;
    [gps, gps_len] = asils.models.drivers.uart_stream(junk, 0, gpp, 25, 145, 0, 1);
    can_id = zeros(8, 1);
    can_id(1) = 512;
    can_dlc = zeros(8, 1);
    can_dlc(1) = 8;
    can_data = zeros(8, 8);
    can_data(1, 1) = 1;
    can_data(1, 5) = 1;
    rot_gi = zeros(8, 1);
    rot_gi(1) = 1;
    [mag_ok, b, gyro_ok, w, sun_ok, sun, es_ok, nadir, st_ok, st_valid, q_st, gps_ok, r, v, h, delta] = asils.models.drivers.drv_read(one, gyro_rx, one, one, st, st_len, gps, gps_len, can_id, can_dlc, can_data, 1, true, true, true, true, true, 1, rot_gi);
    s.mag = b(1);
    s.gyro = w(1);
    s.unit = sun(1);
    s.q = q_st(1, 1);
    s.pos = r(1);
    s.vel = v(1);
    s.h = h(1);
    s.delta = delta(1);
    s.word = asils.models.drivers.q15(1);
    s.valve = 0.001;
    s.lo16 = asils.models.drivers.rd16(0, 128);
    s.hi16 = asils.models.drivers.rd16(255, 127);
    s.lo32 = asils.models.drivers.rd32(0, 0, 0, 128);
    s.hi32 = asils.models.drivers.rd32(255, 255, 255, 127);
end
